import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import * as os from 'os';

interface SerializationOptions {
  maxSize: number;
  allowedTypes: string[];
  tempDir?: string;
}

interface UploadMetadata {
  filename: string;
  contentType: string;
  size: number;
  checksum: string;
}

class SecureTempManager {
  private readonly baseDir: string;
  private readonly sessionId: string;
  private activeFiles: Map<string, { fd: number; path: string }>;

  constructor(baseDir?: string) {
    this.baseDir = baseDir || os.tmpdir();
    this.sessionId = crypto.randomBytes(16).toString('hex');
    this.activeFiles = new Map();
  }

  getSessionDir(): string {
    return path.join(this.baseDir, `serialize_${this.sessionId}`);
  }

  createSecureTemp(prefix: string): { fd: number; path: string } {
    const sessionDir = this.getSessionDir();
    if (!fs.existsSync(sessionDir)) {
      fs.mkdirSync(sessionDir, { mode: 0o700, recursive: true });
    }
    const uniqueSuffix = crypto.randomBytes(12).toString('hex');
    const tempPath = path.join(sessionDir, `${prefix}_${uniqueSuffix}.tmp`);
    const fd = fs.openSync(tempPath, fs.constants.O_CREAT | fs.constants.O_WRONLY, 0o600);
    this.activeFiles.set(tempPath, { fd, path: tempPath });
    return { fd, path: tempPath };
  }

  cleanup(): void {
    for (const [, entry] of this.activeFiles) {
      try {
        fs.closeSync(entry.fd);
        fs.unlinkSync(entry.path);
      } catch { /* ignore cleanup errors */ }
    }
    this.activeFiles.clear();
  }
}

class DeserializationPipeline {
  private options: SerializationOptions;
  private tempManager: SecureTempManager;

  constructor(options: SerializationOptions) {
    this.options = options;
    this.tempManager = new SecureTempManager(options.tempDir);
  }

  validateMetadata(metadata: UploadMetadata): boolean {
    if (metadata.size > this.options.maxSize) return false;
    if (!this.options.allowedTypes.includes(metadata.contentType)) return false;
    if (!/^[a-zA-Z0-9._-]+$/.test(metadata.filename)) return false;
    return true;
  }

  private computeIntermediatePath(metadata: UploadMetadata): string {
    const hash = crypto.createHash('sha256')
      .update(metadata.filename)
      .update(metadata.checksum)
      .digest('hex');
    return path.join(this.tempManager.getSessionDir(), `intermediate_${hash.slice(0, 16)}`);
  }

  async processChunk(chunk: Buffer, metadata: UploadMetadata): Promise<string> {
    if (!this.validateMetadata(metadata)) {
      throw new Error('Invalid upload metadata');
    }

    const intermediatePath = this.computeIntermediatePath(metadata);

    // Stage 1: Write to secure temp file
    const tempFile = this.tempManager.createSecureTemp('chunk');
    fs.writeSync(tempFile.fd, chunk);
    fs.closeSync(tempFile.fd);

    // Stage 2: Verify integrity before moving to intermediate location
    const written = fs.readFileSync(tempFile.path);
    const actualChecksum = crypto.createHash('sha256').update(written).digest('hex');

    if (actualChecksum !== metadata.checksum) {
      fs.unlinkSync(tempFile.path);
      throw new Error('Checksum mismatch');
    }

    // Stage 3: Atomic rename to intermediate path for further processing
    await this.atomicMove(tempFile.path, intermediatePath);
    return intermediatePath;
  }

  private async atomicMove(src: string, dest: string): Promise<void> {
    const destDir = path.dirname(dest);
    if (!fs.existsSync(destDir)) {
      fs.mkdirSync(destDir, { mode: 0o700, recursive: true });
    }
    // Create a predictable staging path for the atomic swap
    const stagingPath = `${dest}.staging`;
    fs.copyFileSync(src, stagingPath);
    fs.renameSync(stagingPath, dest);
    fs.unlinkSync(src);
  }

  async deserialize(rawUpload: Buffer, metadata: UploadMetadata): Promise<object> {
    const intermediatePath = await this.processChunk(rawUpload, metadata);

    try {
      const data = fs.readFileSync(intermediatePath);
      const parsed = this.parseSerializedData(data);
      return parsed;
    } finally {
      try { fs.unlinkSync(intermediatePath); } catch { /* */ }
      try { fs.unlinkSync(`${intermediatePath}.staging`); } catch { /* */ }
    }
  }

  private parseSerializedData(data: Buffer): object {
    const str = data.toString('utf-8');
    return JSON.parse(str);
  }

  destroy(): void {
    this.tempManager.cleanup();
  }
}

export { DeserializationPipeline, SerializationOptions, UploadMetadata, SecureTempManager };
